import {UNITS,PIZZA_SIZES,CATEGORIES,numeric,recipeCost,validateRecipe,mergeCatalog,currentRecipes,mergeEvents,stable,invoicePrice} from './kitchen-core.mjs';
const $=s=>document.querySelector(s),h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2),copy=x=>JSON.parse(JSON.stringify(x));
const money=n=>n===null||n===undefined?'Needs price':new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2}).format(n),date=n=>new Date(n).toLocaleString('en-CA',{timeZone:'America/Toronto',dateStyle:'medium',timeStyle:'short'}),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const unitMoney=n=>n==null?'Needs price':new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',minimumFractionDigits:2,maximumFractionDigits:6}).format(n);
const WKEY='scottys-waste-log-v1',GKEY='scottys-wing-check-v1',tabs=[['home','Home'],['recipes','Recipes'],['ingredients','Ingredients'],['waste','Waste'],['wings','Wings'],['invoices','Invoices'],['sync','Sync & backup']];
let db,state={events:[],source:[],acked:[],cursor:0,owner:null,autoSync:false,postings:{},draft:null},catalog=[],session=null,screen='home',modal=$('#modal'),busy=false,toastTimer,autoTimer,draftTimer,storageReady=false,ingFilter='',installPrompt=null,invoiceDraft=null,capturing=false;
const request=async(url,options={})=>{let r;try{r=await fetch(url,{...options,credentials:'same-origin',cache:'no-store'});}catch{throw Error('No connection. Your local entries remain on this device.');}let data;try{data=await r.json();}catch{throw Error('The server response could not be confirmed. Sign in again from Sync.');}if(!r.ok||data.status&&data.status!=='success'){if(data.signIn){state.signIn=data.signIn;}throw Error(data.message||'The operation was not confirmed. Local entries are still saved.');}return data;};
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('scottys-vision-kitchen',1);r.onupgradeneeded=()=>{r.result.createObjectStore('state');r.result.createObjectStore('files',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function read(store,key){return new Promise((resolve,reject)=>{const t=db.transaction(store),r=key===undefined?t.objectStore(store).getAll():t.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function write(store,value,key){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');if(key===undefined)t.objectStore(store).put(value);else t.objectStore(store).put(value,key);t.oncomplete=()=>resolve();t.onerror=()=>reject(Error('Device storage is full or unavailable. Export your records before closing.'));t.onabort=()=>reject(Error('Saving did not complete. Keep this screen open and export a backup.'));});}
let saving=Promise.resolve();function save(){const snapshot=copy(state);const job=saving.catch(()=>{}).then(()=>write('state',snapshot,'main'));saving=job;return job;}
function notice(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function error(e){notice(e.message||String(e));console.error(e);}
function units(selected='g'){return Object.entries(UNITS).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v.label}</option>`).join('');}
function options(list,selected){return list.map(x=>`<option value="${h(x)}" ${x===selected?'selected':''}>${h(x)}</option>`).join('');}
function field(label,name,value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${h(value)}" ${extra}></div>`;}
function heading(title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">Scotty’s on King · Vision</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function button(label,action,cls='primary',id=''){return `<button type="button" class="${cls}" data-action="${action}" data-id="${h(id)}">${label}</button>`;}
function dialog(content){modal.innerHTML=`<div class="modal-head"><div class="eyebrow">Vision Kitchen</div>${button('✕ Close','close','quiet')}</div>${content}`;if(!modal.open)modal.showModal();}
function localStatus(){const n=state.events.filter(e=>!state.acked.includes(e.id)).length;$('#status').textContent=!storageReady?'Local saving unavailable':busy?'Synchronising…':n?`${n} ${n===1?'entry':'entries'} saved locally · waiting to sync`:`Saved locally${state.lastSync?' · backed up '+date(state.lastSync):' · not yet backed up'}`;}
async function addEvent(kind,entityId,data,at=Date.now(),id=uid()){const e={id,kind,entityId,at,data:copy(data)};state.events=mergeEvents(state.events,[e]);await save();catalog=mergeCatalog(state.source,state.events);localStatus();scheduleSync();return e;}
function scheduleSync(){clearTimeout(autoTimer);if(state.autoSync&&navigator.onLine&&!busy)autoTimer=setTimeout(()=>sync().catch(error),1800);}
function getWaste(){const raw=localStorage.getItem(WKEY);return raw?WasteCore.validateStore(JSON.parse(raw)):null;}
function getWings(){const raw=localStorage.getItem(GKEY);return raw?WingCore.validateStore(JSON.parse(raw)):null;}
function mappedWaste(){return catalog.map(x=>({...x,source:x.source||'Vision',package:x.package||'',visionId:x.visionId||'',gramsEach:x.gramsEach??null,mlEach:x.mlEach??null,confirmed:x.confirmed===true,cost:x.cost??null,active:x.active!==false}));}
async function rebuildLegacy(){
 let w=getWaste();if(w){const records=state.events.filter(x=>x.kind==='waste').map(x=>x.data),voids=state.events.filter(x=>x.kind==='waste_void').map(x=>x.data);for(const r of records)if(!w.records.some(x=>x.id===r.id))w.records.push(r);for(const v of voids)if(!w.voids.some(x=>x.id===v.id))w.voids.push(v);if(catalog.length)w.items=mappedWaste();const setting=state.events.filter(e=>e.kind==='settings'&&e.entityId==='waste-lists').sort((a,b)=>b.at-a.at||b.id.localeCompare(a.id))[0];if(setting){w.employees=setting.data.employees;w.reasons=setting.data.reasons;}WasteCore.validateStore(w);localStorage.setItem(WKEY,JSON.stringify(w));}
 let g=getWings()||{schema:1,batches:[],settings:{sound:false,staff:''}};for(const e of state.events.filter(x=>x.kind==='wing_batch'))if(!g.batches.some(b=>b.id===e.entityId))g.batches.push({...copy(e.data),events:[],round:null});for(const e of state.events.filter(x=>x.kind==='wing_event')){const b=g.batches.find(b=>b.id===e.entityId);if(b&&!b.events.some(v=>v.id===e.data.id))b.events.push(copy(e.data));}for(const b of g.batches)b.events.sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id));WingCore.validateStore(g);localStorage.setItem(GKEY,JSON.stringify(g));
}
async function collectLegacy(){if(capturing)return;capturing=true;try{const incoming=[],now=Date.now(),w=getWaste(),g=getWings();const old=new Set(state.events.map(e=>e.id));if(w){for(const r of w.records){const id='waste:'+r.id;if(!old.has(id))incoming.push({id,kind:'waste',entityId:r.id,at:r.at,data:r});}for(const r of w.voids){const id='waste-void:'+r.id;if(!old.has(id))incoming.push({id,kind:'waste_void',entityId:r.recordId,at:r.at,data:r});}for(const item of w.items){const existing=catalog.find(x=>x.id===item.id);if(existing&&stable({...existing})===stable({...item}))continue;if(!existing||['name','baseUnit','cost','confirmed','basis','costDate','active','visionId','gramsEach','mlEach'].some(k=>stable(existing[k]??null)!==stable(item[k]??null)))incoming.push({id:uid(),kind:'ingredient',entityId:item.id,at:now,data:item});}const last=state.events.filter(e=>e.kind==='settings'&&e.entityId==='waste-lists').sort((a,b)=>b.at-a.at||b.id.localeCompare(a.id))[0],lists={employees:w.employees,reasons:w.reasons};if(!last||stable(last.data)!==stable(lists))incoming.push({id:uid(),kind:'settings',entityId:'waste-lists',at:now,data:lists});}if(g){for(const b of g.batches){const id='wingbatch:'+b.id;if(!old.has(id)){const {events,round,...meta}=b;incoming.push({id,kind:'wing_batch',entityId:b.id,at:b.createdAt,data:meta});}for(const e of b.events){const id='wing:'+b.id+':'+e.id;if(!old.has(id))incoming.push({id,kind:'wing_event',entityId:b.id,at:e.at,data:e});}}}if(incoming.length){state.events=mergeEvents(state.events,incoming);await save();catalog=mergeCatalog(state.source,state.events);localStatus();scheduleSync();}}finally{capturing=false;}}
function render(){screen=location.hash.slice(1)||'home';if(!tabs.some(x=>x[0]===screen))screen='home';$('#nav').innerHTML=tabs.map(([id,label])=>`<a href="#${id}" ${screen===id?'aria-current="page"':''}>${label}</a>`).join('');if(screen==='home')home();if(screen==='recipes')recipes();if(screen==='ingredients')ingredients();if(screen==='invoices')invoices();if(screen==='sync')syncView();if(screen==='waste'||screen==='wings'){$('#main').innerHTML=`<p class="module-note">Saved on this device first. Use <a href="#sync">Sync & backup</a> to copy records online.</p><iframe class="logger" title="${screen==='waste'?'Waste logger':'Wing time and temperature logger'}" src="/modules/${screen}.html"></iframe>`;}localStatus();}
function home(){const rc=currentRecipes(state.events),final=rc.filter(x=>x.heads.some(y=>y.data.finalized)).length,waiting=state.events.filter(x=>x.kind==='invoice').length;$('#main').innerHTML=heading('Your kitchen, in one place.','Make it. Record it. Know what it costs.')+`<div class="grid"><a class="card tool" href="#recipes"><span class="tool-icon">01 / MAKE</span><span class="arrow">↗</span><b>Recipe builder</b><p>Build a special as you work. See the ingredient cost live.</p></a><a class="card tool" href="#waste"><span class="tool-icon">02 / RECORD</span><span class="arrow">↗</span><b>Waste logger</b><p>The familiar two-step form. Item, amount, employee.</p></a><a class="card tool" href="#wings"><span class="tool-icon">03 / CHECK</span><span class="arrow">↗</span><b>Wing logger</b><p>One tray at a time. Actual times and probe readings.</p></a><a class="card tool" href="#invoices"><span class="tool-icon">04 / CAPTURE</span><span class="arrow">↗</span><b>Invoices & receipts</b><p>Photograph on your S24 Ultra. Review details on either device.</p></a></div><div class="actions">${button('＋ Start a recipe','new-recipe')}<a class="button" href="#ingredients">Review ingredient prices</a><button class="install" data-action="install">Install on this tablet</button></div><div class="stat-grid"><div class="panel"><span class="metric">${catalog.filter(x=>x.active).length}</span><small>ingredients available<br>${catalog.filter(x=>x.active&&x.confirmed).length} prices reviewed</small></div><div class="panel"><span class="metric">${final}</span><small>recipes with a<br>finalised card</small></div><div class="panel"><span class="metric">${waiting}</span><small>invoice records<br>awaiting / saved review</small></div></div><p class="notice">Offline work saves on this device. Open <a href="#sync">Sync & backup</a> when the hotspot is available. Prices are CAD; missing costs stay unknown.</p>${!state.lastSync?'<p class="notice warning">Already used the downloaded loggers? Export their JSON backups and import them here to bring those records across.</p>':''}`;updateInstall();}
function freshRecipe(){return {id:uid(),name:'',type:'BatchRecipe',size:'Other / not pizza',yieldQty:'',yieldUnit:'ea',sellPrice:'',notes:'',lines:[],parentRevision:null};}
function recipes(){const saved=currentRecipes(state.events);$('#main').innerHTML=heading('Build while you cook.','Add the amount used. Reviewed ingredient prices do the costing.',button('＋ New recipe','new-recipe'))+(state.draft?`<section class="panel"><div class="eyebrow">Work in progress</div><h2>${h(state.draft.name||'Untitled recipe')}</h2><p>Saved on this device as you type.</p>${button('Continue recipe','continue-recipe')}</section>`:'')+`<h2 style="margin-top:28px">Saved recipes</h2><div class="list">${saved.length?saved.map(r=>r.heads.map(e=>`<article class="panel list-item"><div><h3>${h(e.data.recipe.name)}</h3><small>${h(e.data.recipe.size)} · ${date(e.at)}</small><span class="tag ${e.data.costingSnapshot?.complete?'':'warn'}">${e.data.finalized?'Finalised card':'Draft'} · ${money(e.data.costingSnapshot?.total)}</span>${r.heads.length>1?'<span class="tag warn">Two device revisions — review both</span>':''}</div><div class="actions">${button('View card','card','',e.id)}${button('Edit copy','edit-recipe','quiet',e.id)}</div></article>`).join('')).join(''):'<section class="panel empty">Your recipe cards will appear here.</section>'}</div>`;}
function recipeEditor(){const r=state.draft;$('#main').innerHTML=heading('What are we making?','Costs update as you enter the amount. Staff can add ingredients one at a time.',`<a class="button" href="#recipes" data-action="recipes-list">Recipe list</a>`)+`<form id="recipeForm" novalidate class="panel">${field('Recipe / daily special name','name',r.name,'maxlength="160" placeholder="e.g. Thursday’s chicken special" required')}<div class="row">${field('Finished yield / number of portions','yieldQty',r.yieldQty,'inputmode="decimal" placeholder="Unknown until measured"')}<div class="field"><label for="yieldUnit">Yield unit</label><select id="yieldUnit" name="yieldUnit">${units(r.yieldUnit)}</select></div></div><div class="row"><div class="field"><label for="size">Pizza size / product</label><select id="size" name="size">${options(PIZZA_SIZES,r.size)}</select></div>${field('Selling price per yield unit, before tax','sellPrice',r.sellPrice,'inputmode="decimal" placeholder="Optional · CAD"')}</div><div class="row"><div class="field"><label for="type">Recipe type</label><select id="type" name="type">${options(['BatchRecipe','SubRecipe','PrepItem','Sauce','Dough','Blend'],r.type)}</select></div><div class="field"><label for="notes">Method / preparation notes</label><textarea id="notes" name="notes" rows="2" placeholder="Add steps as you work">${h(r.notes)}</textarea></div></div><div class="toolbar"><h2>Ingredients</h2>${button('＋ Add ingredient','choose-ingredient')}</div><div id="recipeLines">${r.lines.map((l,i)=>recipeLine(l,i)).join('')||'<p class="empty">Start with the first ingredient.</p>'}</div><p class="saving" id="draftStatus">Draft saved locally.</p><div class="error" id="recipeError" hidden></div><div class="actions">${button('Finalise recipe card','finalize','primary accent')}${button('Save draft revision','save-recipe','')}${button('Clear working draft','clear-draft','quiet danger')}</div></form><div class="cost-bar" id="costBar"></div><p class="muted">Ingredient margin excludes labour, overhead, packaging not entered and tax. A blank cost never counts as zero.</p>`;updateCost();}
function recipeLine(l,i){const x=catalog.find(x=>x.id===l.itemId);return `<section class="line" data-line="${i}"><div class="line-top"><strong>${h(x?.name||l.name||'Ingredient unavailable')}</strong>${button('✕','remove-line','quiet danger',i)}</div><div class="row"><div><label for="qty-${i}">Amount used</label><input id="qty-${i}" data-key="qty" inputmode="decimal" value="${h(l.qty)}" placeholder="Amount"></div><div><label for="unit-${i}">Measure</label><select id="unit-${i}" data-key="unit">${units(l.unit)}</select></div><div class="line-price" id="line-price-${i}">—</div></div><small id="line-reason-${i}"></small><details><summary>Cost for this recipe only (optional)</summary><div class="row">${`<div><label for="override-${i}">Cost per unit (CAD)</label><input id="override-${i}" data-key="overrideCost" inputmode="decimal" value="${h(l.overrideCost??'')}" placeholder="Use ingredient price"></div><div><label for="override-unit-${i}">Cost unit</label><select id="override-unit-${i}" data-key="overrideUnit">${units(l.overrideUnit||x?.baseUnit||'g')}</select></div>`}</div><label class="check"><input type="checkbox" data-key="overrideReviewed" ${l.overrideReviewed?'checked':''}>I checked this override and its unit.</label><small>This leaves the shared ingredient price unchanged.</small></details></section>`;}
function readDraft(){const f=$('#recipeForm');if(!f)return;for(const key of ['name','yieldQty','yieldUnit','size','sellPrice','type','notes'])state.draft[key]=f.elements.namedItem(key).value;for(const el of f.querySelectorAll('[data-line]'))for(const input of el.querySelectorAll('[data-key]'))state.draft.lines[+el.dataset.line][input.dataset.key]=input.type==='checkbox'?input.checked:input.value;}
function updateCost(){try{readDraft();const c=recipeCost(state.draft,catalog);c.lines.forEach((l,i)=>{$('#line-price-'+i).textContent=money(l.value);$('#line-reason-'+i).textContent=l.reason||`${unitMoney(l.cost)} / ${l.priceUnit} · ${l.basis}`;});$('#costBar').innerHTML=`<span><small>${c.complete?'Ingredient cost / batch':'Known subtotal · '+c.unpriced+' unpriced'}</small><strong class="${c.complete?'':'incomplete'}">${money(c.complete?c.total:c.subtotal)}${c.complete?'':' + ?'}</strong></span><span><small>Per ${h(UNITS[state.draft.yieldUnit]?.label||'portion')}</small><strong>${c.perPortion===null?'—':money(c.perPortion)}</strong></span><span><small>Ingredient margin</small><strong>${c.margin===null?'—':c.margin.toFixed(1)+'%'}</strong></span>`;$('#recipeError').hidden=true;}catch(e){$('#recipeError').textContent=e.message;$('#recipeError').hidden=false;}}
async function saveDraft(){readDraft();await save();const el=$('#draftStatus');if(el)el.textContent='Draft saved locally · '+date(Date.now());}
function chooseIngredient(){readDraft();dialog(`<h2>Add an ingredient</h2><label for="pickSearch">Search name</label><input id="pickSearch" type="search" autocomplete="off" placeholder="e.g. cheese, flour, wings"><div id="pickResults"></div><a class="button" href="#ingredients" data-action="to-ingredients">Create or review an ingredient</a>`);pickResults('');}
function pickResults(q){const list=catalog.filter(x=>x.active!==false&&x.name.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));$('#pickResults').innerHTML=list.slice(0,40).map(x=>`<button class="search-result" data-action="pick-ingredient" data-id="${h(x.id)}"><span>${h(x.name)}<small>${x.confirmed?unitMoney(x.cost)+' / '+x.baseUnit:'Price needs review'}</small></span><b>＋</b></button>`).join('')||'<p>No matching ingredients. Create one in Ingredients.</p>';}
async function finishRecipe(finalized){readDraft();validateRecipe(state.draft);const r=copy(state.draft),cost=recipeCost(r,catalog),parentRevision=r.parentRevision;delete r.parentRevision;const e=await addEvent('recipe',r.id,{recipe:r,costingSnapshot:cost,finalized,parentRevision});state.draft=null;await save();notice(finalized?'Recipe card saved. Unknown prices remain marked.':'Draft revision saved.');showCard(e.id);}
function showCard(id){const e=state.events.find(x=>x.id===id&&x.kind==='recipe');if(!e)throw Error('Recipe not found.');const {recipe:r,costingSnapshot:c}=e.data;$('#main').innerHTML=`<div class="actions no-print"><a class="button" href="#recipes" data-action="recipes-list">← Recipes</a>${button('Print card','print')}${button('Edit a new revision','edit-recipe','',e.id)}${e.data.finalized?button('Review for Vision Sheets','review-post','',e.id):''}</div><article class="panel recipe-card"><div class="card-head"><div class="eyebrow">Scotty’s on King · Recipe card</div><h1>${h(r.name)}</h1><p>${h(r.size)} · ${h(r.type)} · ${e.data.finalized?'Finalised':'Draft'}</p><small>Saved ${date(e.at)} · CAD · ${h(e.id)}</small></div><p>Yield: <b>${h(r.yieldQty||'Not measured')} ${r.yieldQty?h(UNITS[r.yieldUnit].label):''}</b>${r.sellPrice?' · Selling price before tax: '+money(c.price)+' / '+h(UNITS[r.yieldUnit].label):''}</p><div class="scroll-table"><table><thead><tr><th>Ingredient</th><th>Amount</th><th>Cost basis</th><th>Ingredient cost</th></tr></thead><tbody>${c.lines.map(l=>`<tr><td>${h(l.name)}</td><td>${h(l.qty)} ${h(l.unit)}</td><td>${h(l.basis)}<small>${l.value===null?h(l.reason):unitMoney(l.cost)+' / '+h(l.priceUnit)}</small></td><td>${money(l.value)}</td></tr>`).join('')}</tbody></table></div><div class="cost-bar"><span><small>${c.complete?'Ingredient cost / batch':'Known subtotal; '+c.unpriced+' unpriced'}</small><strong>${money(c.complete?c.total:c.subtotal)}${c.complete?'':' + unknown'}</strong></span><span><small>Per yield unit</small><strong>${c.perPortion===null?'Unknown':money(c.perPortion)}</strong></span><span><small>Ingredient margin</small><strong>${c.margin===null?'Unknown':c.margin.toFixed(1)+'%'}</strong></span></div>${r.notes?`<h2>Method & notes</h2><p class="notes">${h(r.notes)}</p>`:''}<p class="muted">Cost snapshot retained from this revision. Ingredient margin excludes labour, overhead and tax. Unmeasured yield and missing prices remain unknown.</p></article>`;window.scrollTo(0,0);}
function ingredients(){const list=catalog.filter(x=>x.name.toLowerCase().includes(ingFilter.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));$('#main').innerHTML=heading('Know your ingredients.','Review the price and unit once. Future waste entries and recipes use that price.',button('＋ Ingredient','new-ingredient'))+`<div class="actions">${button('Refresh from Vision Sheets','refresh-catalog','')}${button('Export ingredient list','export-catalog','quiet')}</div><p class="notice">${state.catalogAt?'Last live workbook read: '+date(state.catalogAt):'Using the existing ingredient cache; prices need review.'} A workbook refresh brings in source values. Reviewed local prices remain in place until you change them.</p><label for="ingSearch">Find an ingredient</label><input id="ingSearch" type="search" value="${h(ingFilter)}" placeholder="Search ingredients"><p class="muted">${list.length} ingredients · ${catalog.filter(x=>x.confirmed).length} prices reviewed</p><div class="list" id="ingredientList">${list.slice(0,80).map(x=>ingredientRow(x)).join('')}</div>${list.length>80?'<p>Showing the first 80. Search to narrow the list.</p>':''}`;}
function ingredientRow(x){return `<article class="panel list-item"><div><h3>${h(x.name)}</h3><small>${x.cost===null?'Unknown cost':unitMoney(x.cost)+' / '+h(x.baseUnit)} · ${h(x.basis)}</small><span class="tag ${x.confirmed?'':'warn'}">${x.confirmed?'Price reviewed':'Needs review'}</span>${!x.active?'<span class="tag warn">Hidden from staff list</span>':''}<small>${h(x.visionId||'Vision ID pending approval')}</small></div>${button('Review','ingredient','',x.id)}</article>`;}
function ingredientEditor(id=''){const x=catalog.find(x=>x.id===id)||{id:'',name:'',baseUnit:'kg',cost:null,confirmed:false,basis:'Current',costDate:'',category:'Food',active:true};dialog(`<h2>${id?'Review ingredient':'New ingredient'}</h2><form id="ingredientForm" data-id="${h(id)}" novalidate>${field('Ingredient name','itemName',x.name,'maxlength="160" required')}<div class="row"><div class="field"><label for="category">Category</label><select id="category" name="category">${options(CATEGORIES,CATEGORIES.includes(x.category)?x.category:'Other / needs review')}</select></div><div class="field"><label for="baseUnit">Cost unit</label><select id="baseUnit" name="baseUnit">${units(x.baseUnit)}</select></div></div><div class="row">${field('Cost per cost unit, CAD','cost',x.cost??'','inputmode="decimal" placeholder="Blank = unknown"')}${field('Price checked on','costDate',x.costDate||'','type="date"')}</div><div class="field"><label for="basis">Price basis</label><select id="basis" name="basis">${options(['Current','Average','Manual','Imported — review'],x.basis)}</select></div><label class="check"><input name="confirmed" type="checkbox" ${x.confirmed?'checked':''}>I verified this price and its unit.</label><label class="check"><input name="active" type="checkbox" ${x.active?'checked':''}>Show in staff ingredient dropdown</label><details><summary>Measured conversions & Vision mapping</summary><div class="row">${field('Grams per each','gramsEach',x.gramsEach??'','inputmode="decimal" placeholder="Unknown"')}${field('mL per each','mlEach',x.mlEach??'','inputmode="decimal" placeholder="Unknown"')}</div>${field('Approved Vision ingredient ID','visionId',x.visionId||'','placeholder="Leave blank until approved"')}<small>Map only to the same product and stock stage. Weight and volume are never assumed equivalent.</small></details><small class="source">Source: ${h(x.source||'Manual entry')}${x.sourceAt?' · read '+date(x.sourceAt):''}</small><div class="error" hidden></div><div class="actions"><button class="primary" type="submit">Save ingredient locally</button></div></form>`);}
async function ingredientSave(form){const f=new FormData(form),id=form.dataset.id||'LOCAL-'+uid(),old=catalog.find(x=>x.id===id),confirmed=f.has('confirmed'),cost=numeric(f.get('cost')),costDate=String(f.get('costDate')||'');if(!String(f.get('itemName')).trim())throw Error('Name the ingredient.');if(confirmed&&(cost===null||!costDate||costDate>today()||f.get('basis')==='Imported — review'))throw Error('A reviewed price needs its checked-on date and a Current, Average or Manual basis.');const grams=numeric(f.get('gramsEach')),ml=numeric(f.get('mlEach'));if(grams===0||ml===0)throw Error('Measured piece conversions must be positive, or blank.');const x={...(old||{}),id,name:String(f.get('itemName')).trim(),category:f.get('category'),cost,confirmed,costDate,basis:f.get('basis'),baseUnit:f.get('baseUnit'),active:f.has('active'),visionId:String(f.get('visionId')||'').trim(),gramsEach:grams,mlEach:ml,source:old?.source||'Manual review'};await addEvent('ingredient',id,x);await rebuildLegacy();modal.close();if(screen==='ingredients')ingredients();notice('Ingredient saved. Existing recipe cards keep their original costs.');}
async function refreshCatalog(){const result=await request('/api/catalog');if(!Array.isArray(result.items))throw Error('The workbook catalog response was incomplete.');state.source=result.items;state.native=result.native;state.catalogAt=result.at;catalog=mergeCatalog(state.source,state.events);await save();await rebuildLegacy();if(screen==='ingredients')ingredients();notice('Live Vision ingredient list read. Unverified prices still need review.');}
function invoices(){const list=state.events.filter(x=>x.kind==='invoice').sort((a,b)=>b.at-a.at);$('#main').innerHTML=heading('Capture now. Review clearly.','Use the S24 Ultra for receipt photos. Use either screen to check the details.',button('＋ Invoice / receipt','new-invoice'))+`<p class="notice">Photos and drafts can be saved offline. No invoice amount, tax, category or ingredient cost is approved automatically. Keep the original receipts.</p><div class="list">${list.map(e=>`<article class="panel list-item"><div><h3>${h(e.data.vendor||'Supplier not yet entered')}</h3><small>${h(e.data.number||'Invoice number unknown')} · ${h(e.data.date||'Date unknown')}</small><span class="tag warn">${e.data.lines.length} lines · needs review</span><small>${e.data.attachments.length} attachments · saved ${date(e.at)}</small></div>${button('Review','invoice','',e.id)}</article>`).join('')||'<section class="panel empty">Tomorrow’s invoices and receipts can start here.</section>'}</div>`;}
function newInvoice(){invoiceDraft={id:uid(),vendor:'',number:'',date:'',notes:'',attachments:[],lines:[]};invoiceEditor();}
function invoiceEditor(){const x=invoiceDraft;dialog(`<h2>Invoice intake</h2><p>Attach the original, then enter only what you can verify.</p><form id="invoiceForm" novalidate>${field('Supplier / vendor','vendor',x.vendor,'placeholder="Unknown until checked"')}<div class="row">${field('Invoice / receipt number','number',x.number)}${field('Invoice date','invoiceDate',x.date,'type="date"')}</div><div class="field"><label for="cameraPhoto">Take a photo on the phone</label><input class="capture" id="cameraPhoto" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></div><div class="field"><label for="photos">Choose existing photos or PDFs</label><input class="capture" id="photos" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" multiple><small>JPEG, PNG, WebP or PDF · 16 MB each. On the phone, choose Camera if offered.</small></div><div class="file-list" id="invoiceFiles">${x.attachments.map(f=>`<div class="file-row"><span>${h(f.name)}</span><small>Saved locally</small></div>`).join('')}</div><h3 style="margin-top:24px">Ingredient lines</h3><div id="invoiceLines">${x.lines.map((l,i)=>invoiceLine(l,i)).join('')}</div>${button('＋ Add line','invoice-line','')}<div class="field" style="margin-top:18px"><label for="invoiceNotes">Questions / missing details</label><textarea id="invoiceNotes" name="invoiceNotes" rows="3" placeholder="e.g. Is this price per case or per bag?">${h(x.notes)}</textarea></div><div class="error" hidden></div><div class="actions"><button class="primary" type="submit">Save intake for review</button></div><small>Saving intake does not update ingredient costs, inventory or Google Sheets.</small></form>`);}
function invoiceLine(l,i){return `<section class="line" data-invoice-line="${i}"><label for="invoice-item-${i}">Ingredient</label><select id="invoice-item-${i}" data-i-key="itemId"><option value="">Unmapped / needs clarification</option>${catalog.filter(x=>x.active).sort((a,b)=>a.name.localeCompare(b.name)).map(x=>`<option value="${h(x.id)}" ${x.id===l.itemId?'selected':''}>${h(x.name)}</option>`).join('')}</select><div class="field"><label>Description as printed</label><input aria-label="Description line ${i+1}" data-i-key="description" value="${h(l.description||'')}"></div><div class="row"><div class="field"><label>Packages purchased</label><input aria-label="Packages line ${i+1}" data-i-key="packages" inputmode="decimal" value="${h(l.packages||'')}" placeholder="Unknown"></div><div class="field"><label>Net amount in each package</label><input aria-label="Net package quantity line ${i+1}" data-i-key="packQty" inputmode="decimal" value="${h(l.packQty||'')}" placeholder="Unknown"></div></div><div class="row"><div class="field"><label>Package measure</label><select aria-label="Package measure line ${i+1}" data-i-key="packUnit">${units(l.packUnit||'kg')}</select></div><div class="field"><label>Line subtotal before tax / after discounts</label><input aria-label="Net subtotal line ${i+1}" data-i-key="netSubtotal" inputmode="decimal" value="${h(l.netSubtotal??'')}" placeholder="CAD · unknown"></div></div><div class="row"><div class="field"><label>Tax actually shown</label><input aria-label="Tax line ${i+1}" data-i-key="tax" inputmode="decimal" value="${h(l.tax??'')}" placeholder="Blank = unknown"></div><div class="field"><label>Category</label><select aria-label="Category line ${i+1}" data-i-key="category">${options(CATEGORIES,l.category||'Other / needs review')}</select></div></div></section>`;}
function readInvoice(){const f=$('#invoiceForm');if(!f)return;for(const key of ['vendor','number'])invoiceDraft[key]=f.elements.namedItem(key).value;invoiceDraft.date=f.elements.namedItem('invoiceDate').value;invoiceDraft.notes=f.elements.namedItem('invoiceNotes').value;for(const el of f.querySelectorAll('[data-invoice-line]'))for(const input of el.querySelectorAll('[data-i-key]'))invoiceDraft.lines[+el.dataset.invoiceLine][input.dataset.iKey]=input.value;}
async function attachFiles(files){if(!invoiceDraft)return;readInvoice();for(const file of files){if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)||file.size>16*1024*1024||!file.size)throw Error('Use JPEG, PNG, WebP or PDF files under 16 MB.');const meta={id:uid(),name:file.name,type:file.type,size:file.size};await write('files',{...meta,blob:file,synced:false});invoiceDraft.attachments.push(meta);await write('state',invoiceDraft,'invoiceDraft');}invoiceEditor();notice('Attachments saved locally. Save the intake to include them in sync.');}
async function saveInvoice(){readInvoice();for(const l of invoiceDraft.lines){for(const k of ['packages','packQty','netSubtotal','tax'])numeric(l[k]);}if(!invoiceDraft.attachments.length&&!invoiceDraft.lines.length)throw Error('Attach a receipt or enter at least one ingredient line.');await addEvent('invoice',invoiceDraft.id,invoiceDraft);await write('state',null,'invoiceDraft');invoiceDraft=null;modal.close();invoices();notice('Invoice intake saved for review. Ingredient prices are unchanged.');}
async function viewInvoice(id){const e=state.events.find(x=>x.id===id),x=e.data;dialog(`<h2>${h(x.vendor||'Supplier needs review')}</h2><p>${h(x.number||'Invoice # unknown')} · ${h(x.date||'Date unknown')}</p><h3>Original attachments</h3><div class="file-list">${x.attachments.map(f=>`<button data-action="open-file" data-id="${h(f.id)}">Open ${h(f.name)}</button>`).join('')||'<p>No attachment</p>'}</div><h3 style="margin-top:24px">Ingredient review</h3>${x.lines.map((l,i)=>{const p=invoicePrice(l);return `<section class="line"><h3>${h(l.description||catalog.find(x=>x.id===l.itemId)?.name||'Unmapped line')}</h3><p>${h(l.packages||'?')} packages × ${h(l.packQty||'?')} ${h(l.packUnit)} · net subtotal ${l.netSubtotal===''?'Unknown':money(numeric(l.netSubtotal))}</p><p>Candidate ingredient cost: <b>${p?unitMoney(p.cost)+' / '+h(p.baseUnit):'Missing pack quantity / subtotal'}</b></p><small>Tax as entered: ${l.tax===''||l.tax==null?'Unknown':money(numeric(l.tax))} · ${h(l.category)}</small>${p&&l.itemId?button('Review this ingredient price','invoice-price','',e.id+':'+i):'<p class="notice warning">Needs an ingredient mapping and verified package details.</p>'}</section>`;}).join('')}<p>${h(x.notes||'No clarification notes yet.')}</p>${button('Edit a review copy','edit-invoice','',e.id)}<p class="muted">Invoice intake is kept as evidence. Updating a cost requires a separate reviewed ingredient save.</p>`);}
async function openFile(id){const file=await read('files',id);if(file?.blob){const url=URL.createObjectURL(file.blob);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}else{const a=document.createElement('a');a.href='/api/files?id='+encodeURIComponent(id);a.target='_blank';a.rel='noopener';a.click();}}
function syncView(){const pending=state.events.filter(e=>!state.acked.includes(e.id));$('#main').innerHTML=heading('Ready when the hotspot is.','Save on this device first. Synchronise when connected.',button('Sync now','sync'))+`<div class="grid"><section class="panel"><div class="eyebrow">Device → private backup</div><h2>${pending.length} entries waiting</h2><p>${state.lastSync?'Last confirmed sync: '+date(state.lastSync):'This device has not completed a sync.'}</p><p>Connection: <b>${navigator.onLine?'Device reports online':'Offline'}</b><br>Account: <b>${h(session?.user?.name||'Sign in required to sync')}</b></p>${!session?.user?`<a class="button" href="${h(state.signIn||'/signin-with-chatgpt?return_to=%2Fkitchen.html%23sync')}">Sign in to Vision</a>`:''}<label class="check"><input id="autoSync" type="checkbox" ${state.autoSync?'checked':''}>Automatically back up while Vision is open and connected.</label><small>Google Sheets writes always require a separate review and approval.</small></section><section class="panel"><div class="eyebrow">Keep a copy</div><h2>Import & backup</h2><div class="actions">${button('Download data backup','backup','')}${button('Import logger / Vision backup','import','')}</div><p class="muted">Backups include records, draft recipes and ingredient reviews. Receipt originals are separate: keep phone photos and use Sync to copy attachments online.</p><input hidden id="backupInput" type="file" accept=".json,application/json"><small>Old downloaded loggers use separate browser storage. Export their JSON backups and import them here.</small></section><section class="panel wide"><div class="eyebrow">Vision Google Sheets</div><h2>Review before posting</h2><p>Publish reviewed ingredients first to establish approved Vision IDs. Waste posts as a waste record plus a linked inventory decrease. Recipe cards post as recipes and components; saving a recipe does not use stock.</p><div class="actions">${button('Read ingredient list','refresh-catalog','')}${button('Review pending entries','post-list','')}</div><p class="notice warning">Corrections to waste already posted in Sheets need a manager to reconcile the original waste and inventory rows. Local corrections are retained; they do not silently reverse posted stock.</p><small>Invoice intake and wing records back up privately. They do not create purchase receipts or assert cooking / cooling passes in Sheets. Unknown costs and opening stock stay unknown.</small></section><section class="panel wide"><h2>Add Vision to the tablet home screen</h2><ol><li>Open this private link in Chrome and sign in using the same account on both devices.</li><li>Tap Chrome’s three-dot menu → <b>Install app</b> or <b>Add to Home screen</b>.</li><li>Open Vision once while online. Wait for “Offline app ready” below before disconnecting.</li></ol><p id="offlineStatus" class="notice">${h(state.offlineReady?'Offline app ready on this device.':'Offline app is being prepared. Keep this page open while connected.')}</p><button class="install primary" data-action="install">Install Vision Kitchen</button><small>Online sync runs while the app is open. Clearing browser storage can erase unsynced data; download a backup regularly. Protect the tablet with a screen lock.</small></section></div>`;updateInstall();}
async function sync(){if(busy)return;busy=true;localStatus();try{await collectLegacy();await saveDraft();const s=await request('/api/session');session=s;state.signIn=s.signIn;if(!s.user)throw Error('Sign in from Sync to back up this device.');if(state.owner&&state.owner!==s.user.id)throw Error('This device has records from another Vision account. Export them and use the original account; records were not uploaded.');state.owner=s.user.id;let remaining=state.events.filter(e=>!state.acked.includes(e.id));let more=true;do{const chunk=remaining.slice(0,40),r=await request('/api/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({events:chunk,since:state.cursor})});const merged=mergeEvents(state.events,r.events||[]);if(!Array.isArray(r.ack)||chunk.some(e=>!r.ack.includes(e.id)))throw Error('The server did not acknowledge every sent entry. Sync is incomplete.');state.events=merged;state.acked=[...new Set([...state.acked,...r.ack,...(r.events||[]).map(x=>x.id)])];state.cursor=r.cursor;await save();remaining=state.events.filter(e=>!state.acked.includes(e.id));more=r.more||remaining.length>0;}while(more);const used=new Set(state.events.filter(e=>e.kind==='invoice').flatMap(e=>e.data.attachments.map(x=>x.id)));for(const file of await read('files'))if(!file.synced&&used.has(file.id)){const data=new FormData();data.set('id',file.id);data.set('file',file.blob,file.name);await request('/api/files',{method:'POST',body:data});await write('files',{...file,synced:true});}state.lastSync=Date.now();catalog=mergeCatalog(state.source,state.events);await save();await rebuildLegacy();notice('Entries and attached files confirmed in your private backup.');if(screen==='sync')syncView();}finally{busy=false;localStatus();}}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function backup(){await collectLegacy();await saveDraft();download('Scottys_Vision_Backup_'+today()+'.json',{visionSchema:1,exportedAt:Date.now(),state,waste:getWaste(),wings:getWings(),attachmentNote:'Original receipt files are separate. Keep phone originals; sync uploads private copies.'});notice('Data backup downloaded. Keep original receipt photos separately.');}
async function importBackup(file){if(!file||file.size>30*1024*1024)throw Error('Choose a JSON backup under 30 MB.');const value=JSON.parse(await file.text());if(value.visionSchema===1){if(!Array.isArray(value.state?.events))throw Error('Vision backup is missing its records.');for(const e of value.state.events){if(!e.id||!e.entityId||!Number.isSafeInteger(e.at)||!['waste','waste_void','wing_event','wing_batch','recipe','ingredient','invoice','settings'].includes(e.kind))throw Error('Backup includes an invalid entry.');}if(value.state.owner&&state.owner&&value.state.owner!==state.owner)throw Error('This backup belongs to another account.');const merged=mergeEvents(state.events,value.state.events);if(!state.owner&&value.state.owner)state.owner=value.state.owner;if(value.waste)WasteCore.validateStore(value.waste);if(value.wings)WingCore.validateStore(value.wings);state.events=merged;if(!state.source.length)state.source=value.state.source||[];if(!state.draft&&value.state.draft)state.draft=value.state.draft;if(value.waste)mergeWaste(value.waste);if(value.wings)mergeWings(value.wings);}else if(value.records&&value.items){mergeWaste(value);}else if(value.batches){mergeWings(value);}else throw Error('This is not a recognised Vision or logger backup.');await collectLegacy();catalog=mergeCatalog(state.source,state.events);await save();await rebuildLegacy();render();notice('Backup merged. Original times and IDs retained; sync still needs confirmation.');}
function mergeWaste(incoming){const v=WasteCore.validateStore(incoming),old=getWaste();if(!old){localStorage.setItem(WKEY,JSON.stringify(v));return;}const next=copy(old);for(const key of ['records','voids','items','employees','reasons'])for(const x of v[key]){const existing=next[key].find(y=>y.id===x.id);if(!existing)next[key].push(x);else if(['records','voids'].includes(key)&&stable(existing)!==stable(x))throw Error('Conflicting waste record. Import stopped; review the backups.');}WasteCore.validateStore(next);localStorage.setItem(WKEY,JSON.stringify(next));}
function mergeWings(incoming){const v=WingCore.validateStore(incoming),old=getWings();if(!old){localStorage.setItem(GKEY,JSON.stringify(v));return;}const next=copy(old);for(const b of v.batches){const prior=next.batches.find(x=>x.id===b.id);if(!prior)next.batches.push(b);else{for(const e of b.events){const existing=prior.events.find(x=>x.id===e.id);if(existing&&stable(existing)!==stable(e))throw Error('Conflicting wing reading. Import stopped.');if(!existing)prior.events.push(e);}}}WingCore.validateStore(next);localStorage.setItem(GKEY,JSON.stringify(next));}
async function postList(){await collectLegacy();const voided=new Set(state.events.filter(e=>e.kind==='waste_void').map(e=>e.data.recordId));const list=state.events.filter(e=>e.kind==='ingredient'||e.kind==='waste'&&!voided.has(e.entityId)||e.kind==='recipe'&&e.data.finalized).sort((a,b)=>b.at-a.at);dialog(`<h2>Review for Vision Sheets</h2><p>Nothing posts until you review its proposed rows and approve.</p><div class="list">${list.slice(0,80).map(e=>`<article class="panel"><b>${h(e.kind==='recipe'?e.data.recipe.name:e.kind==='waste'?e.data.itemName:e.data.name)}</b><small>${h(e.kind)} · ${date(e.at)} · ${h(state.postings[e.id]?'Posted / confirmed':'Not confirmed posted')}</small>${button('Preview proposed rows','review-post','',e.id)}</article>`).join('')||'<p>No new records yet. Add an ingredient, recipe or waste entry first.</p>'}</div>`);}
let postPreview=null;
async function reviewPost(id){await sync();const result=await request('/api/vision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({eventId:id,mode:'preview'})});if(result.alreadyConfirmed){state.postings[id]=result;await save();notice('This entry is already confirmed in Vision Sheets.');return;}postPreview=result;dialog(`<h2>Approve these Vision entries?</h2><p>${h(result.summary)}</p>${result.blocks.map(b=>`<h3>${h(b.sheet)} · ${h(b.range)}</h3><div class="scroll-table"><table><tbody>${b.rows.map(row=>row.map((v,i)=>`<tr><th>${h(b.headers[i])}</th><td>${v===null||v===''?'<i>Unknown / blank</i>':h(v)}</td></tr>`).join('')).join('')}</tbody></table></div>`).join('')}<p class="notice warning">This writes the displayed rows to Vision OS. Check the item, quantity, unit, price and date. Stock balances are not established by this action.</p><div class="actions">${button('Approve & post these rows','approve-post')}${button('Cancel','close','')}</div>`);}
async function approvePost(){if(!postPreview)return;const x=postPreview;postPreview=null;const r=await request('/api/vision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({eventId:x.eventId,mode:'commit',approval:x.approval})});state.postings[x.eventId]=r;await save();if(r.visionId){const old=catalog.find(y=>y.id===x.entityId);if(old){await addEvent('ingredient',old.id,{...old,visionId:r.visionId});await rebuildLegacy();}}modal.close();notice('Vision Sheets rows read back and confirmed.');}
function updateInstall(){document.querySelectorAll('.install').forEach(el=>el.style.display=installPrompt?'inline-flex':'none');}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;updateInstall();});
window.addEventListener('hashchange',()=>{saveDraft().catch(error);render();window.scrollTo(0,0);});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='VISION_CHANGED')collectLegacy().catch(error);});window.addEventListener('storage',e=>{if(e.key===WKEY||e.key===GKEY)collectLegacy().catch(error);});window.addEventListener('online',()=>{localStatus();scheduleSync();});window.addEventListener('offline',localStatus);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){collectLegacy().catch(error);saveDraft().catch(error);}});
document.addEventListener('input',e=>{if(e.target.closest('#recipeForm')){updateCost();clearTimeout(draftTimer);draftTimer=setTimeout(()=>saveDraft().catch(error),300);}if(e.target.closest('#invoiceForm')&&invoiceDraft){readInvoice();clearTimeout(draftTimer);draftTimer=setTimeout(()=>write('state',invoiceDraft,'invoiceDraft').catch(error),300);}if(e.target.id==='pickSearch')pickResults(e.target.value);if(e.target.id==='ingSearch'){ingFilter=e.target.value;const list=catalog.filter(x=>x.name.toLowerCase().includes(ingFilter.toLowerCase())).sort((a,b)=>a.name.localeCompare(b.name));$('#ingredientList').innerHTML=list.slice(0,80).map(ingredientRow).join('');}});
document.addEventListener('change',e=>{if(e.target.id==='autoSync'){state.autoSync=e.target.checked;save().then(scheduleSync).catch(error);}if(e.target.id==='photos'||e.target.id==='cameraPhoto')attachFiles([...e.target.files]).catch(error);if(e.target.id==='backupInput')importBackup(e.target.files[0]).catch(error);});
document.addEventListener('submit',async e=>{if(!['ingredientForm','invoiceForm','recipeForm'].includes(e.target.id))return;e.preventDefault();try{if(e.target.id==='ingredientForm')await ingredientSave(e.target);if(e.target.id==='invoiceForm')await saveInvoice();if(e.target.id==='recipeForm')await saveDraft();}catch(err){const box=e.target.querySelector('.error');if(box){box.hidden=false;box.textContent=err.message;}else error(err);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;e.preventDefault();try{b.disabled=true;if(a==='close'){modal.close();return;}if(a==='new-recipe'){if(state.draft){dialog(`<h2>Continue the working recipe?</h2><p>${h(state.draft.name||'Untitled recipe')} is saved locally.</p>${button('Continue this recipe','continue-recipe')}${button('Save it as a draft first','close','')}`);return;}state.draft=freshRecipe();await save();if(location.hash!=='#recipes'){history.replaceState(null,'','#recipes');render();}recipeEditor();}
 if(a==='continue-recipe'){modal.close();recipeEditor();}if(a==='recipes-list'){await saveDraft();recipes();}if(a==='choose-ingredient')chooseIngredient();if(a==='pick-ingredient'){const x=catalog.find(x=>x.id===id);state.draft.lines.push({itemId:id,name:x.name,qty:'',unit:x.baseUnit,overrideCost:'',overrideUnit:x.baseUnit,overrideReviewed:false});await save();modal.close();recipeEditor();const input=$('#qty-'+(state.draft.lines.length-1));input?.scrollIntoView({block:'center'});input?.focus();}if(a==='remove-line'){readDraft();state.draft.lines.splice(+id,1);await save();recipeEditor();}if(a==='finalize'||a==='save-recipe')await finishRecipe(a==='finalize');if(a==='clear-draft'){dialog(`<h2>Clear this working draft?</h2><p>Saved recipe revisions and cards will remain.</p>${button('Clear working draft','confirm-clear','danger')}${button('Keep it','close','')}`);}if(a==='confirm-clear'){state.draft=null;await save();modal.close();recipes();}if(a==='card')showCard(id);if(a==='edit-recipe'){if(state.draft)throw Error('Save or clear the current working recipe before editing another.');const x=state.events.find(e=>e.id===id);state.draft={...copy(x.data.recipe),parentRevision:id};await save();recipeEditor();}if(a==='print')window.print();if(a==='new-ingredient')ingredientEditor();if(a==='ingredient')ingredientEditor(id);if(a==='to-ingredients'){modal.close();location.hash='#ingredients';}if(a==='refresh-catalog')await refreshCatalog();if(a==='export-catalog')download('Scottys_Ingredient_Reviews_'+today()+'.json',{exportedAt:Date.now(),ingredients:catalog});if(a==='sync')await sync();if(a==='backup')await backup();if(a==='import')$('#backupInput').click();if(a==='new-invoice'){const old=await read('state','invoiceDraft');if(old){invoiceDraft=old;invoiceEditor();}else newInvoice();}if(a==='invoice-line'){readInvoice();invoiceDraft.lines.push({itemId:'',description:'',packages:'',packQty:'',packUnit:'kg',netSubtotal:'',tax:'',category:'Other / needs review'});await write('state',invoiceDraft,'invoiceDraft');invoiceEditor();}if(a==='invoice')await viewInvoice(id);if(a==='edit-invoice'){invoiceDraft=copy(state.events.find(e=>e.id===id).data);invoiceDraft.id=uid();invoiceDraft.reviews=id;invoiceEditor();}if(a==='open-file')await openFile(id);if(a==='invoice-price'){const split=id.lastIndexOf(':'),x=state.events.find(e=>e.id===id.slice(0,split)).data,l=x.lines[+id.slice(split+1)],p=invoicePrice(l);ingredientEditor(l.itemId);$('#cost').value=p.cost;$('#baseUnit').value=p.baseUnit;$('#basis').value='Current';$('#costDate').value=x.date||'';$('#ingredientForm [name=confirmed]').checked=false;notice('Candidate price entered. Check the original and approve the ingredient price.');}if(a==='post-list')await postList();if(a==='review-post')await reviewPost(id);if(a==='approve-post')await approvePost();if(a==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;updateInstall();}}
 catch(err){error(err);}finally{b.disabled=false;}});
async function boot(){try{db=await openDB();const saved=await read('state','main');if(saved)state={...state,...saved};storageReady=true;if(!state.source.length){const response=await fetch('/ingredient-cache.json');const seed=await response.json();state.source=Array.isArray(seed)?seed:seed.items||[];state.source=state.source.map(x=>({...x,confirmed:false}));}catalog=mergeCatalog(state.source,state.events);let w=getWaste();if(!w){const seed=await (await fetch('/ingredient-cache.json')).json();w=WasteCore.emptyStore?WasteCore.emptyStore(seed):null;if(!w){w={schema:1,items:mappedWaste(),employees:[],reasons:[{id:'spoilage',name:'Spoilage',active:true},{id:'overproduction',name:'Overproduction',active:true},{id:'expired',name:'Expired',active:true},{id:'dropped',name:'Dropped / damaged',active:true},{id:'quality',name:'Quality reject',active:true},{id:'staff',name:'Staff meal',active:true},{id:'returned',name:'Customer return',active:true}],records:[],voids:[],settings:{location:'',lastEmployee:''}};}WasteCore.validateStore(w);localStorage.setItem(WKEY,JSON.stringify(w));}await collectLegacy();await rebuildLegacy();await save();render();try{session=await request('/api/session');state.signIn=session.signIn;if(screen==='sync')syncView();}catch{}if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').then(async r=>{await navigator.serviceWorker.ready;if(r.active||r.waiting){state.offlineReady=true;await save();const el=$('#offlineStatus');if(el)el.textContent='Offline app ready on this device.';}}).catch(e=>{state.offlineReady=false;console.warn('Offline setup incomplete',e);});}if(state.autoSync)scheduleSync();}catch(e){storageReady=false;$('#main').innerHTML=heading('Local records need attention.','Nothing has been overwritten.')+`<p class="error">${h(e.message)}</p><p>Keep the original downloaded loggers and backups. Do not clear browser storage.</p>`;localStatus();console.error(e);}}
boot();
